p"><span class="nav-icon"><?= po_icon('settings') ?></span><span>Settings</span></a><a href="../../index.html"><span class="nav-icon"><?= po_icon('logout') ?></span><span>Log Out</span></a></nav></aside><div class="content"><header class="topbar"><div class="title"><div class="title-mark">D</div><div><strong>Department of the Interior and Local Government</strong><small>Province of Surigao del Sur Ã¢â‚¬Â¢ Provincial Office Dashboard</small></div></div><div class="tools"><div class="search-placeholder">Search dashboard...</div><a class="notification" href="notifications.php" aria-label="Notifications"><?= po_icon('notifications') ?><span><?= htmlspecialchars((string)$notificationCount) ?></span></a><div class="profile"><div class="avatar"><?php if ($profilePhoto): ?><img src="<?= htmlspecialchars($profilePhoto) ?>" alt="PO User profile photo" style="width:100%;height:100%;object-fit:cover;border-radius:inherit;display:block;"><?php else: ?><?= htmlspecialchars(strtoupper(substr($userName,0,1))) ?><?php endif; ?></div><div><strong><?= htmlspecialchars($userName) ?></strong><small>Provincial Office</small></div></div></div></header><main><div class="page-heading"><h1>Reports</h1><p>Monitor FO municipality and city submissions sent to the Provincial Office.</p></div><section class="tracking-card" aria-labelledby="tracking-title"><div class="tracking-header"><h2 id="tracking-title">PO Submission Tracking</h2><p>Review, approve, or return submitted reports and keep the LGU response history current.</p><div class="filters"><input id="search" type="search" placeholder="Search report, reference number, or LGU..." aria-label="Search reports"><select id="lguFilter" aria-label="Filter by LGU"><option value="">All LGUs / Cities</option></select><select id="statusFilter" aria-label="Filter by status"><option value="">All statuses</option><option value="PENDING">Pending</option><option value="UNDER REVIEW">Under Review</option><option value="APPROVED">Approved</option><option value="RETURNED">Returned</option></select><button class="button secondary" id="refresh" type="button">Refresh</button></div></div><div id="tableContainer" class="table-wrap"><div class="loading">Loading submissions...</div></div><div class="table-footer"><span id="countLabel">0 entries</span><div class="pager"><button id="previous" type="button" aria-label="Previous page">&lsaquo;</button><span id="pageLabel">1 / 1</span><button id="next" type="button" aria-label="Next page">&rsaquo;</button></div></div></section></main></div></div>
