<script>
const API='../shared/auth/po_reports_api.php';let rows=[],page=1,selected=null;const pageSize=10;const $=(id)=>document.getElementById(id);const esc=(value)=>String(value??'').replace(/[&<>"']/g,(char)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));const date=(value)=>{if(!value)return'Not submitted';const parsed=new Date(String(value).replace(' ','T'));return Number.isNaN(parsed.getTime())?esc(value):parsed.toLocaleString([],{month:'short',day:'numeric',year:'numeric',hour:'2-digit',minute:'2-digit'})};const statusClass=(value)=>value==='APPROVED'?'approved':value==='RETURNED'?'returned':value==='UNDER REVIEW'?'review':'';
async function load(){ $('tableContainer').innerHTML='<div class="loading">Loading submissions...</div>';try{const response=await fetch(API+'?action=list');const data=await response.json();if(!data.success)throw new Error(data.error);rows=data.reports||[];const current=$('lguFilter').value;$('lguFilter').innerHTML='<option value="">All LGUs / Cities</option>'+(data.lgus||[]).sort().map((lgu)=>`<option value="${esc(lgu)}">${esc(lgu)}</option>`).join('');$('lguFilter').value=current;const initialStatus=new URLSearchParams(window.location.search).get('status');if(initialStatus&&[...$('statusFilter').options].some((option)=>option.value===initialStatus.toUpperCase()))$('statusFilter').value=initialStatus.toUpperCase();page=1;render()}catch(error){$('tableContainer').innerHTML=`<div class="empty">${esc(error.message||'Unable to load submissions.')}</div>`;$('countLabel').textContent='0 entries'}}
function filtered(){const search=$('search').value.toLowerCase().trim(),lgu=$('lguFilter').value,status=$('statusFilter').value;return rows.filter((row)=>(!search||`${row.title} ${row.reference_number} ${row.lgu_name}`.toLowerCase().includes(search))&&(!lgu||row.lgu_name===lgu)&&(!status||row.status===status))}function render(){const items=filtered(),totalPages=Math.max(1,Math.ceil(items.length/pageSize));page=Math.min(page,totalPages);const visible=items.slice((page-1)*pageSize,page*pageSize);$('countLabel').textContent=`${items.length?(page-1)*pageSize+1:0}-${Math.min(page*pageSize,items.length)} of ${items.length} entries`;$('pageLabel').textContent=`${page} / ${totalPages}`;$('previous').disabled=page===1;$('next').disabled=page>=totalPages;if(!visible.length){$('tableContainer').innerHTML='<div class="empty">No submitted FO responses match the selected filters.</div>';return}$('tableContainer').innerHTML=`<table class="tracking-table"><thead><tr><th>Report</th><th>LGU / City</th><th>Submission</th><th>Date Submitted to PO</th><th>Date Approved by PO</th><th>Returned Reason</th></tr></thead><tbody>${visible.map((row)=>`<tr class="tracking-row" tabindex="0" role="button"><td><button class="report-title" type="button" data-id="${row.id}" data-recipient="${row.user_id||0}">${esc(row.title)}</button><small>${esc(row.reference_number||'No reference number')}</small></td><td><strong>${esc(row.lgu_name)}</strong><small>${esc(row.full_name||row.assigned_name||'')}</small></td><td><span class="status ${statusClass(row.status)}">${esc(row.status)}</span></td><td>${date(row.response_at)}</td><td>${row.approved_at?date(row.approved_at):'Not approved'}</td><td>${row.returned_reason?esc(row.returned_reason):'-'}</td></tr>`).join('')}</tbody></table>`;document.querySelectorAll('.report-title').forEach((button)=>button.addEventListener('click',()=>openDetail(button.dataset.id,button.dataset.recipient)));document.querySelectorAll('.tracking-row').forEach((row)=>{row.addEventListener('click',(event)=>{if(!event.target.closest('button')){const button=row.querySelector('.report-title');openDetail(button.dataset.id,button.dataset.recipient)}});row.addEventListener('keydown',(event)=>{if((event.key==='Enter'||event.key===' ')&&!event.target.closest('button')){event.preventDefault();const button=row.querySelector('.report-title');openDetail(button.dataset.id,button.dataset.recipient)}})})}
async function openDetail(id,recipient){selected={id,recipient};$('detailModal').classList.add('active');$('detailBody').innerHTML='<div class="loading">Loading report details...</div>';$('returnBox').classList.remove('active');try{const data=await(await fetch(`${API}?action=detail&id=${encodeURIComponent(id)}&recipient_user_id=${encodeURIComponent(recipient)}`)).json();if(!data.success)throw new Error(data.error);const report=data.report,response=data.response||{};$('detailTitle').textContent=report.title||'Report details';const currentStatus=response.status==='APPROVED'?'APPROVED':response.status==='RETURNED'?'RETURNED':response.response_at?'UNDER REVIEW':'PENDING';const canReview=['SUBMITTED','OVERDUE','UNDER REVIEW'].includes(String(response.status||'').toUpperCase());$('detailBody').innerHTML=`<div class="detail-grid"><div><strong>LGU / City</strong><span>${esc(response.lgu_name||report.creator_office||report.recipient_office||'Municipality / City')}</span></div><div><strong>Status</strong><span class="status ${statusClass(currentStatus)}">${esc(currentStatus)}</span></div><div><strong>Date submitted</strong><span>${date(response.response_at)}</span></div><div><strong>Date reviewed / approved</strong><span>${date(response.reviewed_at||(response.status==='APPROVED'?report.completed_at:null))}</span></div><div><strong>Reference number</strong><span>${esc(report.reference_number||'Not available')}</span></div><div><strong>PO due date</strong><span>${date(report.due_at)}</span></div></div><div class="detail-section"><h3>Report information</h3><p>${esc(report.details||'No report description provided.')}</p></div><div class="detail-section"><h3>FO response</h3><p>${esc(response.response||report.fo_response||'No response submitted yet.')}</p></div>`;$('modalActions').innerHTML=canReview?'<button class="btn secondary" type="button" onclick="toggleReturnReason()">Return</button><button class="btn primary" type="button" onclick="review(\'APPROVE\')">Approve</button>':''}catch(error){$('detailBody').innerHTML=`<div class="empty">${esc(error.message||'Unable to load report details.')}</div>`;$('modalActions').innerHTML=''}}ef="${esc('../shared/auth/download_document.php?id='+encodeURIComponent(file.id)+'&mode=inline')}" target="_blank" rel="noopener">${esc(file.original_name||file.file_name)}</a>`).join(''):'<p>No submitted files.</p>'}</div><div class="detail-section"><h3>Submission history</h3>${(data.history||[]).length?data.history.map((item)=>`<p>${esc(item.action)} - ${date(item.created_at)}${item.full_name?` - ${esc(item.full_name)}`:''}</p>`).join(''):'<p>No history available.</p>'}</div>${response.returned_reason?`<div class="detail-section"><h3>Returned reason</h3><p>${esc(response.returned_reason)}</p></div>`:''}`;if(canReview){$('modalActions').innerHTML='<button class="button secondary" id="returnButton" type="button">Return to FO</button><button class="button" id="approveButton" type="button">Approve report</button>';$('approveButton').addEventListener('click',()=>review('APPROVE'));$('returnButton').addEventListener('click',()=>{$('returnBox').classList.add('active');$('returnReason').focus();$('modalActions').innerHTML='<button class="button secondary" id="cancelReturn" type="button">Cancel</button><button class="button" id="confirmReturn" type="button">Confirm return</button>';$('cancelReturn').addEventListener('click',()=>openDetail(id,recipient));$('confirmReturn').addEventListener('click',()=>review('RETURN'))})}}catch(error){$('detailBody').innerHTML=`<div class="empty">${esc(error.message||'Unable to load report details.')}</div>`}}
async function review(decision){if(decision==='RETURN'){const reason=$('returnReason').value.trim();if(!reason){$('returnReason').focus();alert('Please enter a return reason.');return}if(!window.confirm('Are you sure you want to return this submission to the FO?'))return;submitReview('RETURN',reason)}else if(decision==='APPROVE'){if(!window.confirm('Are you sure you want to approve this submission?'))return;submitReview('APPROVE','')}}async function submitReview(decision,reason){const approveBtn=document.querySelector('.modal-actions .btn.primary');const returnBtn=document.querySelector('.modal-actions .btn.secondary');if(approveBtn)approveBtn.disabled=true;if(returnBtn)returnBtn.disabled=true;if(approveBtn)approveBtn.textContent='Processing...';if(returnBtn)returnBtn.textContent='Processing...';try{const result=await(await fetch(API+'?action=review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:selected.id,recipient_user_id:Number(selected.recipient),decision:decision,reason:reason})})).json();if(!result.success)throw new Error(result.error);const successMsg=decision==='APPROVE'?'Submission approved successfully!':'Submission returned successfully!';alert(successMsg);closeModal();await load()}catch(error){alert(error.message||'The action failed. Please try again.');if(approveBtn){approveBtn.disabled=false;approveBtn.textContent='Approve'}if(returnBtn){returnBtn.disabled=false;returnBtn.textContent='Return'}}}function closeModal(){$('detailModal').classList.remove('active');selected=null;$('returnReason').value='';$('returnBox').classList.remove('active')}function toggleReturnReason(){const isActive=$('returnBox').classList.toggle('active');if(isActive)$('returnReason').focus()}$('search').addEventListener('input',()=>{page=1;render()});$('lguFilter').addEventListener('change',()=>{page=1;render()});$('statusFilter').addEventListener('change',()=>{page=1;render()});$('refresh').addEventListener('click',load);$('previous').addEventListener('click',()=>{page--;render()});$('next').addEventListener('click',()=>{page++;render()});$('closeModal').addEventListener('click',closeModal);$('detailModal').addEventListener('click',(event)=>{if(event.target.id==='detailModal')closeModal()});load();
</script>
<script>
function enhanceGroupedReports() {
	document.querySelectorAll('.tracking-row').forEach((tableRow, index) => {
		const titleButton = tableRow.querySelector('.report-title');
		const report = rows.find((item) => String(item.id) === String(titleButton?.dataset.id));
		if (!report || !Array.isArray(report.recipients) || report.recipients.length < 1 || report.recipient_office !== 'All Municipalities / Cities' || tableRow.dataset.grouped === 'true') return;
		const recipients = report.recipients.filter((recipient) => recipient.response_at);
		if (!recipients.length) return;
		const cells = tableRow.querySelectorAll('td');
		const recipientCell = cells[1];
		if (!titleButton || !recipientCell || cells.length < 6) return;
		const select = document.createElement('select');
		select.className = 'report-recipient-select';
		select.setAttribute('aria-label', 'Select municipality or city response');
		recipients.forEach((recipient, recipientIndex) => {
			const option = document.createElement('option');
			option.value = recipient.user_id || 0;
			option.textContent = recipient.lgu_name;
			option.dataset.index = recipientIndex;
			select.appendChild(option);
		});
		const selectedRecipient = recipients.findIndex((recipient) => recipient.response_at) >= 0 ? recipients.findIndex((recipient) => recipient.response_at) : 0;
		select.selectedIndex = selectedRecipient;
		recipientCell.replaceChildren(select);
		const updateSelectedResponse = () => {
			const recipient = recipients[Number(select.selectedOptions[0]?.dataset.index || 0)];
			titleButton.dataset.recipient = recipient.user_id || 0;
			cells[2].innerHTML = `<span class="status ${statusClass(recipient.status)}">${esc(recipient.status)}</span>`;
			cells[3].textContent = date(recipient.response_at);
			cells[4].textContent = recipient.approved_at ? date(recipient.approved_at) : 'Not approved';
			cells[5].textContent = recipient.returned_reason || '-';
		};
		select.addEventListener('click', (event) => event.stopPropagation());
		select.addEventListener('change', updateSelectedResponse);
		updateSelectedResponse();
		tableRow.dataset.grouped = 'true';
	});
}
new MutationObserver(enhanceGroupedReports).observe(document.getElementById('tableContainer'), { childList: true });
</script>
<script>
const originalOpenDetail = window.openDetail;
window.openDetail = async function (id, recipient) {
	selected = { id, recipient };
	$('detailModal').classList.add('active');
	$('detailBody').innerHTML = '<div class="loading">Loading report responses...</div>';
	$('modalActions').innerHTML = '';
	$('returnBox').classList.remove('active');
	try {
		const data = await (await fetch(`${API}?action=detail&id=${encodeURIComponent(id)}&recipient_user_id=${encodeURIComponent(recipient || 0)}`)).json();
		if (!data.success) throw new Error(data.error);
		const responses = data.responses || [];
		const selectedResponse = data.response || responses[0] || {};
		const responseStatus = (response) => response.status || (response.response_at ? 'UNDER REVIEW' : 'PENDING');
		const responseRows = responses.map((response, index) => `<div class="report-response-entry"><button type="button" class="report-response-row" data-recipient="${response.user_id || 0}"><strong>#${index + 1} ${esc(response.lgu_name || 'Municipality / City')}</strong><small>${esc(response.full_name || response.username || 'FO User')} | ${date(response.response_at)} | ${esc(responseStatus(response))}</small></button><div class="report-response-preview"><strong>FO response</strong><div class="report-response-text">${esc(response.response || 'No response submitted yet.')}</div></div></div>`).join('');
		$('detailTitle').textContent = data.report.title || 'Report details';
		$('detailBody').innerHTML = `<div class="detail-section"><h3>FO responses ranked by first submission</h3><div class="report-response-list">${responseRows || '<div class="empty">No FO response submitted yet.</div>'}</div></div><div id="selectedResponseDetails"></div>`;
		const renderSelectedResponse = (response) => {
			selected = { id, recipient: response.user_id || 0 };
			const currentStatus = responseStatus(response);
			$('selectedResponseDetails').innerHTML = `<div class="detail-grid"><div><strong>Selected FO</strong><span>${esc(response.lgu_name || 'No response selected')}</span></div><div><strong>Submitted by</strong><span>${esc(response.full_name || response.username || 'Not submitted')}</span></div><div><strong>Date submitted to PO</strong><span>${date(response.response_at)}</span></div><div><strong>Status</strong><span class="status ${statusClass(currentStatus)}">${esc(currentStatus)}</span></div></div><div class="detail-section fo-response"><h3>FO response</h3><p class="report-response-text">${esc(response.response || 'No response submitted yet.')}</p></div>`;
			const canReview = ['SUBMITTED', 'OVERDUE', 'UNDER REVIEW'].includes(String(response.status || '').toUpperCase());
			$('modalActions').innerHTML = canReview ? '<button class="btn secondary" type="button" onclick="toggleReturnReason()">Return</button><button class="btn primary" type="button" onclick="review(\'APPROVE\')">Approve</button>' : '';
		};
		document.querySelectorAll('.report-response-row').forEach((button) => button.addEventListener('click', () => {
			const entry = button.closest('.report-response-entry');
			const response = responses.find((item) => String(item.user_id) === String(button.dataset.recipient)) || responses[0];
			document.querySelectorAll('.report-response-entry.expanded').forEach((item) => { if (item !== entry) item.classList.remove('expanded'); });
			entry.classList.toggle('expanded');
			renderSelectedResponse(response);
		}));
		renderSelectedResponse(selectedResponse);
	} catch (error) {
		$('detailBody').innerHTML = `<div class="empty">${esc(error.message || 'Unable to load report responses.')}</div>`;
	}
};

function setGroupedReportTargets() {
	document.querySelectorAll('.report-title').forEach((button) => {
		const report = rows.find((item) => String(item.id) === String(button.dataset.id));
		if (report?.recipient_office === 'All Municipalities / Cities') button.dataset.recipient = '0';
	});
}
new MutationObserver(setGroupedReportTargets).observe(document.getElementById('tableContainer'), { childList: true });
</script>
</body>
